mapper.insert:

/* saleson.shop.disposable.TempEncDataMapper.insertTempData  임시 암호화 정보 저장 */
INSERT INTO G_TEMP_ENC_DATA
(
	DATA_ID
	, ENC_DATA
)
VALUE
(
	#{dataId}
	, #{encData}
)

mapper.delete:

/* saleson.shop.disposable.TempEncDataMapper.deleteTempDataByDataId  아이디로 임시 암호화 정보 삭제 */
DELETE G_TEMP_ENC_DATA
WHERE DATA_ID = #{dataId}

mapper.select:

/* saleson.shop.disposable.TempEncDataMapper.selectTempDataCnt  임시 암호화 정보 존재 여부 조회 */
SELECT
	COUNT(*)
FROM G_TEMP_ENC_DATA
WHERE 1=1
AND DATA_ID = #{dataId}
